import React, { useState, useEffect } from 'react';
import Sidebar from '../components/Sidebar';
import Header from '../components/Header';
import api from '../services/api';
import { Bell, CheckCircle, AlertCircle, Info, RefreshCw } from 'lucide-react';

const NotificationsPage = () => {
  const [notifications, setNotifications] = useState([]);
  const [summary, setSummary] = useState(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    fetchNotifications();
    fetchSummary();
  }, []);

  const fetchNotifications = async () => {
    try {
      const response = await api.get('/notifications?limit=20');
      setNotifications(response.data);
    } catch (error) {
      console.error('Error fetching notifications:', error);
    }
  };

  const fetchSummary = async () => {
    try {
      const response = await api.get('/notifications/summary');
      setSummary(response.data);
    } catch (error) {
      console.error('Error fetching summary:', error);
    }
  };

  const scanForOutdated = async () => {
    setLoading(true);
    try {
      await api.post('/notifications/scan');
      await fetchNotifications();
      await fetchSummary();
    } catch (error) {
      console.error('Error scanning:', error);
    } finally {
      setLoading(false);
    }
  };

  const markAsRead = async (id) => {
    try {
      await api.put(`/notifications/${id}/read`);
      fetchNotifications();
      fetchSummary();
    } catch (error) {
      console.error('Error marking as read:', error);
    }
  };

  const getIcon = (type) => {
    switch(type) {
      case 'outdated': return <AlertCircle className="text-red-500" size={20} />;
      case 'missing_info': return <Info className="text-yellow-500" size={20} />;
      default: return <Bell className="text-blue-500" size={20} />;
    }
  };

  if (loading && !notifications.length) {
    return (
      <div className="flex">
        <Sidebar />
        <div className="ml-64 flex-1">
          <Header />
          <div className="p-8 flex items-center justify-center h-96">
            <div className="text-center">
              <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-blue-600 mx-auto"></div>
              <p className="mt-4 text-gray-600">Loading notifications...</p>
            </div>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="flex">
      <Sidebar />
      <div className="ml-64 flex-1">
        <Header />
        
        <div className="p-8 mt-16">
          <div className="flex justify-between items-center mb-6">
            <h1 className="text-2xl font-bold text-gray-800">Notifications</h1>
            <button
              onClick={scanForOutdated}
              className="bg-blue-600 text-white px-4 py-2 rounded-lg flex items-center gap-2 hover:bg-blue-700"
            >
              <RefreshCw size={20} />
              Scan for Issues
            </button>
          </div>
          
          {summary && (
            <div className="grid grid-cols-1 md:grid-cols-3 gap-4 mb-6">
              <div className="bg-blue-50 rounded-lg p-4">
                <p className="text-sm text-blue-600">Total Notifications</p>
                <p className="text-2xl font-bold text-blue-700">{summary.total}</p>
              </div>
              <div className="bg-yellow-50 rounded-lg p-4">
                <p className="text-sm text-yellow-600">Unread</p>
                <p className="text-2xl font-bold text-yellow-700">{summary.unread}</p>
              </div>
              <div className="bg-red-50 rounded-lg p-4">
                <p className="text-sm text-red-600">High Priority</p>
                <p className="text-2xl font-bold text-red-700">{summary.by_priority?.high || 0}</p>
              </div>
            </div>
          )}
          
          <div className="bg-white rounded-xl shadow-sm border border-gray-200 overflow-hidden">
            {notifications.length === 0 ? (
              <div className="text-center p-8 text-gray-500">
                <CheckCircle className="mx-auto mb-2" size={48} />
                <p>No notifications at this time</p>
                <p className="text-sm mt-2">Click "Scan for Issues" to check for outdated records</p>
              </div>
            ) : (
              <div className="divide-y">
                {notifications.map((notif) => (
                  <div key={notif.id} className={`p-4 ${!notif.is_read ? 'bg-blue-50' : ''}`}>
                    <div className="flex items-start gap-3">
                      {getIcon(notif.type)}
                      <div className="flex-1">
                        <p className="text-gray-800">{notif.message}</p>
                        <p className="text-xs text-gray-500 mt-1">
                          {new Date(notif.created_at).toLocaleString()}
                        </p>
                      </div>
                      {!notif.is_read && (
                        <button
                          onClick={() => markAsRead(notif.id)}
                          className="text-blue-600 text-sm hover:text-blue-800"
                        >
                          Mark as read
                        </button>
                      )}
                    </div>
                  </div>
                ))}
              </div>
            )}
          </div>
        </div>
      </div>
    </div>
  );
};

export default NotificationsPage;
